SINA_SMART["bacterio1-enterobacteria-1"] = {"lecture":"bacterio1-enterobacteria-1","title":"Enterobacteriaceae I: E. coli and Klebsiella","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"bacterio1-enterobacteria-1:e0","text":"Enterobacteriaceae: Gram-negative bacilli, oxidase −, nitrate +, glucose fermenters, facultative anaerobes.","topic":"The family Enterobacteriaceae","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-1:e1","text":"Antigens: O (somatic), H (flagellar), K (capsular).","topic":"The family Enterobacteriaceae","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-1:e2","text":"E. coli: lactose + (pink on MacConkey); ~90% of UTIs.","topic":"The family Enterobacteriaceae","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-1:e3","text":"K1 E. coli: neonatal meningitis and septicaemia.","topic":"Escherichia coli","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-1:e4","text":"ETEC toxins (watery); EIEC invasive (dysentery); EHEC Shiga toxin (bloody, HUS).","topic":"Escherichia coli","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-1:e5","text":"Morocco: rising resistance, frequent ESBL in urinary E. coli.","topic":"E. coli: diagnosis and treatment","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-1:e6","text":"Uncomplicated cystitis: fosfomycin or nitrofurantoin; severe ESBL: carbapenems.","topic":"E. coli: diagnosis and treatment","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-1:e7","text":"Klebsiella: capsulated, non-motile, mucoid; pneumonia, UTI, nosocomial.","topic":"Klebsiella pneumoniae","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-1:e8","text":"Klebsiella naturally resistant to ampicillin; ESBL → carbapenem; CRKP → colistin.","topic":"Klebsiella pneumoniae","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-1:e9","text":"Prevention: hand hygiene, contact precautions, device limits, stewardship.","topic":"Klebsiella pneumoniae","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"15pk5n9":"a","1sp4b13":"a","cywwv3":"a","mj0841":"a","1aep9hb":"a","tppo1g":"a","1vl533p":"a","7insdr":"a","150gmqa":"a","1xs0zui":"a","q0ubxz":"a","1xm7mba":"a","vnyhwc":"a","1cz454s":"a","1ckp43k":"x"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"bacterio1-enterobacteria-1:e0":{"s":0,"u":["Enterobacteriaceae: Gram-negative bacilli, oxidase −, nitrate +, glucose fermenters, facultative anaerobes.","Shared features: oxidase negative , nitrate reductase positive , glucose fermenters, facultative anaerobes , non-sporing, growing easily on ordinary media at 35-37 °C; motile with peritrichous flagella ( E. coli , most Salmonella ) or non-motile ( Shigella , Klebsiella ).","A large, heterogeneous family of clinically important Gram-negative bacilli (27 genera and over 100 species of medical interest)."],"dp":[]},"bacterio1-enterobacteria-1:e1":{"s":0,"u":["Antigens: O (somatic), H (flagellar), K (capsular).","Identification uses biochemical profiles (lactose, indole, methyl red, Voges-Proskauer, citrate, H₂S, urease), antigens ( O somatic, H flagellar, K capsular) and molecular methods."],"dp":[]},"bacterio1-enterobacteria-1:e2":{"s":0,"u":["E. coli: lactose + (pink on MacConkey); ~90% of UTIs.","On MacConkey, E. coli is a pink lactose fermenter (metallic green sheen on EMB); Salmonella and Shigella are pale non-fermenters on Hektoen, XLD or SS agar, Salmonella with black H₂S centres."],"dp":[]},"bacterio1-enterobacteria-1:e3":{"s":1,"u":["K1 E. coli: neonatal meningitis and septicaemia.","Extra-intestinal disease : urinary tract infection (about 90% of UTIs , ascending from the gut flora, attaching by pili: urgency, burning, frequency, pelvic pain, haematuria); neonatal infections by K1 -capsulated strains transmitted from the mother (about 80% of neonatal meningitis and 40% of neonatal septicaemia in the lecture; fever, apnoea, poor feeding, jaundice, seizures); intra-abdominal, bone, skin infections and septicaemia."],"dp":[]},"bacterio1-enterobacteria-1:e4":{"s":1,"u":["ETEC toxins (watery); EIEC invasive (dysentery); EHEC Shiga toxin (bloody, HUS).","Intestinal pathotypes : ETEC (LT and ST enterotoxins, watery diarrhoea, no invasion), EPEC (infant gastroenteritis, no spread), EIEC (Shigella-like invasion of colonic cells: dysentery with blood and leucocytes), EHEC ( Shiga toxins Stx1/Stx2: abundant bloody diarrhoea without leucocytes, systemic toxin effects, haemolytic uraemic syndrome), plus EAEC and DAEC."],"dp":[]},"bacterio1-enterobacteria-1:e5":{"s":2,"u":["Morocco: rising resistance, frequent ESBL in urinary E. coli.","In Morocco resistance is high and rising, especially in UTIs, with frequent ESBL producers: fluoroquinolones and third-generation cephalosporins are less reliable empirically; fosfomycin or nitrofurantoin for uncomplicated cystitis; carbapenems (± an aminoglycoside) for severe ESBL infections; always guided by the antibiogram."],"dp":[]},"bacterio1-enterobacteria-1:e6":{"s":2,"u":["Uncomplicated cystitis: fosfomycin or nitrofurantoin; severe ESBL: carbapenems.","In Morocco resistance is high and rising, especially in UTIs, with frequent ESBL producers: fluoroquinolones and third-generation cephalosporins are less reliable empirically; fosfomycin or nitrofurantoin for uncomplicated cystitis; carbapenems (± an aminoglycoside) for severe ESBL infections; always guided by the antibiogram."],"dp":[]},"bacterio1-enterobacteria-1:e7":{"s":3,"u":["Klebsiella: capsulated, non-motile, mucoid; pneumonia, UTI, nosocomial.","A capsulated , non-motile Gram-negative bacillus forming large mucoid colonies ; a gut commensal, also in soil and water, and an indicator of faecal contamination; spread by direct contact and in hospitals.","It causes pneumonia (dense lobar consolidation with a 'bulging fissure', necrosis), urinary infections , septicaemia in the immunocompromised and many nosocomial infections ."],"dp":[]},"bacterio1-enterobacteria-1:e8":{"s":3,"u":["Klebsiella naturally resistant to ampicillin; ESBL → carbapenem; CRKP → colistin.","Treatment : Klebsiella is naturally resistant to ampicillin (chromosomal penicillinase).","Hospital strains: piperacillin-tazobactam or amikacin if susceptible; ESBL strains (frequent in Moroccan hospitals): carbapenems ± amikacin; carbapenem-resistant (CRKP) : colistin, tigecycline, combinations under specialist guidance; hvKp: ceftriaxone or fluoroquinolone if susceptible."],"dp":[]},"bacterio1-enterobacteria-1:e9":{"s":3,"u":["Prevention: hand hygiene, contact precautions, device limits, stewardship.","Prevention: hand hygiene , contact precautions and isolation for MDR carriers, limiting catheters and ventilators, ICU bundles, antibiotic stewardship, screening and environmental cleaning."],"dp":[{"h":"Why hand hygiene beats new antibiotics","t":"Carbapenem-resistant Klebsiella leaves only a few toxic drugs such as colistin, and resistance to those is appearing. But the organism does not fly: in hospitals it travels on hands, stethoscopes, sinks and catheters from colonised to vulnerable patients. Cleaning hands at the WHO's five moments, isolating carriers and removing catheters as early as possible break that chain for every species at once, which is why infection control is often more powerful than any single new drug. Source: the lecture's Klebsiella prevention table."}]}},"meta":{"15pk5n9":{"a":"recall","vg":"bacterio1-enterobacteria-1:e0/recall/1"},"1sp4b13":{"a":"recall","vg":"bacterio1-enterobacteria-1:e1/recall/1"},"cywwv3":{"a":"recall","vg":"bacterio1-enterobacteria-1:e2/recall/1"},"mj0841":{"a":"relationship","vg":"bacterio1-enterobacteria-1:e3/relationship/1"},"1aep9hb":{"a":"recall","vg":"bacterio1-enterobacteria-1:e3/recall/1"},"tppo1g":{"a":"recall","vg":"bacterio1-enterobacteria-1:e4/recall/1"},"1vl533p":{"a":"recall","vg":"bacterio1-enterobacteria-1:e4/recall/2"},"7insdr":{"a":"recall","vg":"bacterio1-enterobacteria-1:e4/recall/3"},"150gmqa":{"a":"recall","vg":"bacterio1-enterobacteria-1:e6/recall/1"},"1xs0zui":{"a":"recall","vg":"bacterio1-enterobacteria-1:e6/recall/2"},"q0ubxz":{"a":"recall","vg":"bacterio1-enterobacteria-1:e7/recall/1"},"1xm7mba":{"a":"recall","vg":"bacterio1-enterobacteria-1:e7/recall/2"},"vnyhwc":{"a":"recall","vg":"bacterio1-enterobacteria-1:e8/recall/1"},"1cz454s":{"a":"recall","vg":"bacterio1-enterobacteria-1:e9/recall/1"}},"explRev":"4cafb4b5530b"};
